@AfterAll
    static void cleanup() {
        if (connection != null) {
            for (String key : connection.sync().keys("dset|*" + FILTER_ID + "*")) {
                connection.sync().del(key);
            }
            connection.close();
        }
        if (redisClient != null) redisClient.shutdown();
    }

