@BeforeClass
  public static void setupCluster() throws Exception {
    String configName = "aijoinCloudCollectionConfig";
    int nodeCount = 5;
    configureCluster(nodeCount)
        .withSolrXml(
            DEFAULT_CLOUD_SOLR_XML.replace(
                "<solr>", "<solr><int name=\"indexSearcherExecutorThreads\">4</int>"))
        .addConfig(configName, configset("auxindexjoin"))
        .configure();

    Map<String, String> collectionProperties = new HashMap<>();

    // create a collection holding data for the "to" (unique-key) side of the JOIN
    int shards = 2;
    int replicas = 2;
    CollectionAdminRequest.createCollection(toColl, configName, shards, replicas)
        .setProperties(collectionProperties)
        .process(cluster.getSolrClient());

    // get the set of nodes where replicas for the "to" collection exist
    Set<String> nodeSet = new HashSet<>();
    ZkStateReader zkStateReader = cluster.getZkStateReader();
    ClusterState cs = zkStateReader.getClusterState();
    for (Slice slice : cs.getCollection(toColl).getActiveSlices())
      for (Replica replica : slice.getReplicas()) nodeSet.add(replica.getNodeName());
    assertTrue(nodeSet.size() > 0);

    // deploy the single-shard "from" collection to every node where the "to" collection exists,
    // so AuxIndexJoinQParserPlugin's collocation lookup always finds a local "from" replica -- and
    // stays
    // on the single-shard fast path, which skips the router-field cross-checks that a sharded
    // "from" collection would otherwise require
    CollectionAdminRequest.createCollection(fromColl, configName, 1, 4)
        .setCreateNodeSet(String.join(",", nodeSet))
        .setProperties(collectionProperties)
        .process(cluster.getSolrClient());

    toDocId = indexToDoc(1001, "b");
    indexFromDoc(2001, toDocId, "c");
    indexFromDoc(2002, toDocId, "d"); // a second "from" doc mapping to the same "to" doc: still M:1

    Thread.sleep(1000); // so the commits fire
  }

@AfterClass
  public static void shutdown() {
    log.info(
        "DistribAuxIndexJoinFromCollectionTest logic complete ... deleting the {} and {} collections",
        toColl,
        fromColl);

    // try to clean up
    for (String c : new String[] {toColl, fromColl}) {
      try {
        CollectionAdminRequest.Delete req = CollectionAdminRequest.deleteCollection(c);
        req.process(cluster.getSolrClient());
      } catch (Exception e) {
        // don't fail the test
        log.warn("Could not delete collection {} after test completed due to:", c, e);
      }
    }

    log.info("DistribAuxIndexJoinFromCollectionTest succeeded ... shutting down now!");
  }

@BeforeClass
  public static void beforeTests() throws Exception {
    solrRule.startSolr();

    // the aijoin configset declares no schemaFactory, so loading it file-based would let the
    // default managed-schema factory rewrite the source-tree conf dir; work on a temp copy
    Path aijoinConfigSet = createTempDir("auxindexjoin");
    PathUtils.copyDirectory(configset("auxindexjoin"), aijoinConfigSet.resolve("conf"));
    solrRule.newCollection().withConfigSet(aijoinConfigSet).create();

    // "minimal" uses ClassicIndexSchemaFactory, which never writes, so it's safe to use in place
    solrRule.newCollection(FROM_CORE).withConfigSet(configset("minimal")).create();

    SolrClient toSide = solrRule.getSolrClient();

    // departments: the "to"/unique side of every join below, one doc per dept_id_s value
    toSide.add(
        List.of(
            doc("id", "10", "dept_id_s", "Engineering", "text_s", "These guys develop stuff"),
            doc("id", "11", "dept_id_s", "Marketing", "text_s", "These guys make you look good"),
            doc("id", "12", "dept_id_s", "Sales", "text_s", "These guys sell stuff"),
            doc("id", "13", "dept_id_s", "Support", "text_s", "These guys help customers")));

    // employees: the "from"/many side, each with exactly one dept_s value
    toSide.add(employees());
    toSide.commit();

    // aijoinFromCore holds the same employees, for the cross-core variant of the same joins
    SolrClient fromSide = solrRule.getSolrClient(FROM_CORE);
    fromSide.add(employees());
    fromSide.commit();
  }

