                from(from)
                        .to("aws-bedrock://label"
                            + "?bedrockRuntimeClient=#bedrockClient"
                            + "&bedrockRuntimeAsyncClient=#bedrockAsyncClient"
                            + "&operation=" + operation
                            + "&pojoRequest=true"
                            + "&region=us-east-1"
                            + "&accessKey=unused"
                            + "&secretKey=unused");
            }
        });
        camelContext.start();
        template = camelContext.createProducerTemplate();
