@BeforeEach
    void startMuteServer() throws Exception {
        server = new ServerSocket(0);
        accepted = new CountDownLatch(1);
        acceptor = new Thread(() -> {
            while (!stopped) {
                try (Socket socket = server.accept()) {
                    accepted.countDown();
                    // hold the connection open and write nothing at all, so the client is left waiting on a read;
                    // draining the request blocks until the client gives up and closes
                    socket.getInputStream().transferTo(OutputStream.nullOutputStream());
                } catch (IOException e) {
                    return;
                }
            }
        }, "mute-http-server");
        acceptor.setDaemon(true);
        // the loop guard is set before the thread that reads it. Nothing depends on that order today: this class
        // uses the default PER_METHOD lifecycle, so every test gets a fresh instance with the field already false.
        // It would matter under PER_CLASS, where @AfterEach leaves it true for the next test
        stopped = false;
        acceptor.start();
    }

@AfterEach
    void stopMuteServer() throws Exception {
        stopped = true;
        server.close();
        acceptor.join(TimeUnit.SECONDS.toMillis(5));
    }

